let words f =
  let before = Gc.minor_words () in
  let result = f () in
  (result, Gc.minor_words () -. before)

let slow n =
  let acc = ref [] in
  for i = 1 to n do acc := !acc @ [ i ] done;
  !acc

let fast n =
  let acc = ref [] in
  for i = 1 to n do acc := i :: !acc done;
  List.rev !acc

let () =
  let a, slow_words = words (fun () -> slow 2000) in
  let b, fast_words = words (fun () -> fast 2000) in
  Printf.printf "same result: %b\n" (a = b);
  Printf.printf "quadratic append allocates over 100x more: %b\n" (slow_words > 100. *. fast_words)

